 * yolo-twice look for pele diagrams, shared by the website and the pitch deck.
 *
 * pele colours everything through --pele-* variables and SVG presentation attributes,
 * so CSS rules here restyle the output without re-rendering. Set the --pele-* basics
 * (bg, fg, muted, line, surface, border, accent, font) on the host; this file adds:
 *
 *   --yt-pele-1 … --yt-pele-4   node colours, cycled per node (the deck's four tag colours)
 *   --yt-pele-store             colour of cylinder (storage) nodes
 *
 * The outer <div class="pele"> becomes a dotted canvas card; the inner <svg class="pele">
 * gets tinted, outlined nodes with a soft glow, calmer lines and pill-shaped edge labels.
 */

.pele {
  --yt-pele-1: #6cb6ff;
  --yt-pele-2: #c39bff;
  --yt-pele-3: #e3b341;
  --yt-pele-4: #4ac26b;
  --yt-pele-store: #fd7a2e;
}

/* ---------- the card the diagram sits on ---------- */
div.pele {
  box-sizing: border-box;
  padding: 1.75rem 1.5rem;
  border-radius: 16px;
  border: 1px solid var(--pele-border);
  background:
    radial-gradient(circle, color-mix(in srgb, var(--pele-muted) 26%, transparent) 1px, transparent 1.5px) 0 0 / 20px 20px,
    linear-gradient(160deg,
      color-mix(in srgb, var(--pele-surface) 85%, transparent),
      color-mix(in srgb, var(--pele-surface-alt) 45%, transparent));
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--pele-fg) 6%, transparent);
  text-align: center;
}
div.pele > svg.pele {
  display: block;
  margin: 0 auto;
  overflow: visible;
}

/* ---------- nodes: tinted fill, coloured outline, soft glow ---------- */
svg.pele .pele-nodes > .pele-node { --n: var(--yt-pele-1); }
svg.pele .pele-nodes > .pele-node:nth-child(4n + 2) { --n: var(--yt-pele-2); }
svg.pele .pele-nodes > .pele-node:nth-child(4n + 3) { --n: var(--yt-pele-3); }
svg.pele .pele-nodes > .pele-node:nth-child(4n + 4) { --n: var(--yt-pele-4); }
svg.pele .pele-nodes > .pele-node.pele-shape-cyl { --n: var(--yt-pele-store); }
/* sequence actors appear twice (top and bottom), so they share one colour */
svg.pele .pele-nodes > .pele-node.pele-actor { --n: var(--pele-accent); }

svg.pele .pele-node {
  filter: drop-shadow(0 3px 10px color-mix(in srgb, var(--n) 22%, transparent));
  transition: filter 160ms ease;
}
svg.pele .pele-node:hover {
  filter: drop-shadow(0 4px 16px color-mix(in srgb, var(--n) 45%, transparent));
}
svg.pele .pele-node > :is(rect, path, polygon, circle, ellipse) {
  stroke: var(--n);
  stroke-width: 1.5px;
}
svg.pele .pele-node > :is(rect, path, polygon, circle, ellipse):not([fill="none"]) {
  fill: color-mix(in srgb, var(--n) 15%, var(--pele-surface));
}
svg.pele .pele-node > rect { rx: 10px; }
svg.pele .pele-node .pele-label {
  fill: var(--pele-fg);
  font-weight: 600;
}

/* ---------- edges: thinner, muted, arrowheads to match ---------- */
svg.pele .pele-edge > path:not(.pele-marker) {
  stroke: color-mix(in srgb, var(--pele-line) 85%, transparent);
  stroke-width: 1.6px;
}
svg.pele .pele-edge > .pele-marker {
  fill: var(--pele-line);
}
/* dotted edges (rewinds, replies) drift slowly in their direction */
svg.pele .pele-edge > path[stroke-dasharray] {
  animation: yt-pele-flow 4s linear infinite;
}
@keyframes yt-pele-flow {
  to { stroke-dashoffset: -56; } /* a multiple of both pele dash patterns (7 and 8) */
}

/* edge labels: small pills that sit on the line */
svg.pele .pele-edge-label > rect {
  fill: var(--pele-surface);
  stroke: var(--pele-border);
  stroke-width: 1px;
  rx: 9px;
}
svg.pele .pele-edge-label > text {
  fill: var(--pele-muted);
  font-size: 13px;
  font-weight: 500;
}

/* ---------- sequence diagrams ---------- */
svg.pele .pele-lifeline {
  stroke: var(--pele-border);
  stroke-dasharray: 2 6;
  stroke-linecap: round;
}
svg.pele .pele-note > rect {
  fill: color-mix(in srgb, var(--yt-pele-3) 14%, var(--pele-surface));
  stroke: color-mix(in srgb, var(--yt-pele-3) 70%, transparent);
}
svg.pele .pele-message + .pele-message { } /* placeholder kept empty on purpose: messages use the edge rules */

/* ---------- subgraphs ---------- */
svg.pele .pele-cluster > rect {
  fill: color-mix(in srgb, var(--pele-accent) 6%, transparent);
  stroke: color-mix(in srgb, var(--pele-accent) 40%, transparent);
  stroke-dasharray: 4 4;
  rx: 14px;
}

@media (prefers-reduced-motion: reduce) {
  svg.pele .pele-edge > path[stroke-dasharray] { animation: none; }
  svg.pele .pele-node { transition: none; }
}
